-- =============================================================================
-- English Lab - V16: seed de actividades para los objetivos 7-9
-- Lleva PAST (id 7), COMP (id 8) y MOD (id 9) de 10 a 100 actividades.
-- 90 filas nuevas por objetivo, ids explicitos 661-930.
-- level y skill son los del objetivo en V11 (A2/B1, grammar).
-- category_id: PAST -> 2 (tiempos verbales), COMP -> 3 (adjetivos), MOD -> 5.
-- La clave sigue viviendo SOLO en el jsonb `content` (answer/accepted);
-- jamas viaja al navegador (el DTO de estudiante la omite).
-- =============================================================================

-- Igual que en V13: una base de pruebas reutilizada puede tener actividades
-- autoincrementales dentro del rango reservado. Se liberan SOLO actividades de
-- prueba (objetivos fuera del seed 1-12; la API no permite crear objetivos, asi
-- que en produccion esta sentencia no borra nada). attempts/assignments caen en
-- cascada por sus FK.
delete from activities
where id between 661 and 930
  and objective_id not between 1 and 12;

insert into activities (id, objective_id, type, level, skill, title, content, category_id) overriding system value values
