-- Salvaguarda: si una base de pruebas reutilizada tenia actividades con estos
-- ids pero de objetivos creados por tests, se eliminan (en produccion no borra
-- nada porque todos los objetivos del seed estan entre 1 y 12).
delete from activities
where id between 661 and 930
  and objective_id not between 1 and 12;

-- avanzar la secuencia de activities al maximo id sembrado
select setval(pg_get_serial_sequence('activities', 'id'), (select max(id) from activities));
